export const completeSalesRows=Array.from({length:59},(_,day)=>['A','B'].map((product,line)=>{
 const quantity=(line+1)*(day%7+1),sales=quantity*(line?20:10)*(day>=31?1.2:1);
 return {'Order ID':'O'+day,'Line ID':String(line+1),'Customer ID':'C'+day%3,'Product ID':product,'Order Date':new Date(Date.UTC(2026,0,day+1)).toISOString().slice(0,10),Revenue:sales,Cost:sales/2,Quantity:quantity,'Gross Sales':sales+2,'Discount Amount':2,'Refund Amount':0,'Refund Eligible Sales':sales,'Returned Quantity':0,'Gross Sold Quantity':quantity,Category:line?'Office':'Furniture',Status:'Completed',Currency:'USD'};
})).flat();
